#include <atcoder/modint>
#if TYPE>=4
#include <boost/multiprecision/cpp_int.hpp>
#endif
#include SOURCE
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <utility>
#include <vector>
struct Ring {
 std::uint64_t x;
 Ring(std::int64_t v=0):x(static_cast<std::uint64_t>(v)){}
 Ring(const Ring& other):x(other.x){}
 Ring& operator=(const Ring& other){x=other.x;return *this;}
 friend Ring operator+(Ring a,Ring b){a.x+=b.x;return a;}
 friend Ring operator-(Ring a,Ring b){a.x-=b.x;return a;}
 friend bool operator==(const Ring&a,const Ring&b){return a.x==b.x;}
};
#if TYPE==0
using Value=atcoder::modint998244353;
static std::uint64_t number(Value x){return x.val();}
#elif TYPE==1
using Value=std::int64_t;
static std::uint64_t number(Value x){return static_cast<std::uint64_t>(x);}
#elif TYPE==2
using Value=std::uint64_t;
static std::uint64_t number(Value x){return x;}
#elif TYPE==4 || TYPE==5
using Value=boost::multiprecision::cpp_int;
static std::uint64_t number(const Value& x){return static_cast<std::uint64_t>(x & ((Value(1)<<64)-1));}
#else
using Value=Ring;
static std::uint64_t number(Value x){return x.x;}
#endif
int main(int argc,char**argv){
 if(argc!=4)return 1;
 const int n=std::atoi(argv[1]),mode=std::atoi(argv[2]),reps=std::atoi(argv[3]);
 using UF=RollbackWeightedUnionFind<Value>;using Status=typename UF::MergeResult;
 std::mt19937 rng(61022);std::vector<std::pair<int,int>> edges;
 if(mode==0)for(int step=1;step<n;step*=2)for(int i=0;i<n;i+=2*step)edges.emplace_back(i,i+step);
 else{}
 if(mode==1)for(int i=1;i<n;++i)edges.emplace_back(0,i);
 if(mode>=2)for(int i=0;i<n;++i)edges.emplace_back(static_cast<int>(rng()%n),static_cast<int>(rng()%n));
 UF uf(n);uf.reserve_history(static_cast<std::size_t>(n)*2);
 const auto make_value=[](int v){
#if TYPE==5
 return Value((Value(v)<<256)+v);
#else
 return Value(v);
#endif
 };
 const auto merge=[&](int a,int b){return uf.unite_checked(a,b,make_value(b)-make_value(a));};
 if(mode==2||mode==3||mode==6||mode==8)for(int i=1;i<n;++i)(void)merge(0,i);
 if(mode==5||mode==10||mode==11)for(int step=1;step<n;step*=2)for(int i=0;i<n;i+=2*step)(void)merge(i,i+step);
 if(mode==7)for(int i=1;i<n/2;++i){(void)merge(0,i);(void)merge(n/2,n/2+i);}
 if(mode==9)for(int i=0;i<n;i+=4)for(int j=1;j<4;++j)(void)merge(i,i+j);
 if(mode==13)for(int i=1;i<n;++i)(void)merge(0,i);
 if(mode==14)for(int i=0;i<n;i+=2)(void)merge(i,i+1);
 const auto base=uf.get_state();std::uint64_t checksum=0;
 const auto run=[&](int count){for(int r=0;r<count;++r){
  if(mode==9||mode>=12){const auto groups=uf.groups();for(const auto&g:groups){checksum+=g.size();checksum+=g.front();}}
  else for(auto[a,b]:edges){
   if(mode==5||mode==6||mode==7){const auto d=uf.try_diff(a,b);checksum+=d?number(*d):1;}
   else if(mode==10)checksum+=number(uf.diff(a,b));
   else if(mode==11)checksum+=number(uf.root_with_weight(a).second);
   else {checksum+=merge(a,b)==Status::Merged;if(mode==3)uf.undo();}
  }
  if(mode==0)for(std::size_t i=0;i<edges.size();++i)uf.undo();else uf.rollback(base);
  checksum+=static_cast<unsigned>(uf.get_state())+static_cast<unsigned>(uf.component_count());
 }};
 run(1);checksum=0;
 const auto begin=std::chrono::steady_clock::now();run(reps);const auto end=std::chrono::steady_clock::now();
 if(uf.get_state()!=base)return 2;
 std::printf("%jd %ju\n",static_cast<std::intmax_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count()),static_cast<std::uintmax_t>(checksum));
}
